FRAGEN["_Kurs/FB2/B2_Physikalische-Grundlagen/B2.1_Segeltheorie.html"] = {n: "B.2.1", t: "Segeltheorie", q: [{"q": "Wie fällt der wahre Wind gegenüber dem scheinbaren ein?", "opts": ["Vorlicher", "Achterlicher", "Genau gleich", "Senkrecht"], "correct": 1, "expl": "Der wahre Wind fällt immer achterlicher ein als der scheinbare."}, {"q": "Wodurch wird die Jacht am Wind angetrieben?", "opts": ["Durch Schieben", "Durch Auftrieb am gewölbten Segel", "Durch den Motor", "Durch Strömung"], "correct": 1, "expl": "Von hart am Wind bis raumschot treibt der Auftrieb an, ähnlich einer Tragfläche."}, {"q": "Wo entsteht der Sog (Unterdruck) am Segel?", "opts": ["Auf der Luvseite", "Auf der Leeseite", "Am Unterliek", "Am Mast"], "correct": 1, "expl": "Auf der Leeseite ist die Strömung schneller – dort entsteht der Unterdruck (Sog)."}, {"q": "Warum luvt eine Jacht in einer Bö an?", "opts": ["Der Anker greift", "Sie krängt stärker, das luvgierige Drehmoment nimmt zu", "Der Motor startet", "Die Fock backt"], "correct": 1, "expl": "Bei stärkerer Krängung wandert der Lateralschwerpunkt nach Lee – das luvgierige Drehmoment verstärkt sich."}, {"q": "Was hilft gegen zunehmende Luvgierigkeit?", "opts": ["Vorsegel vergrößern und Groß bauchig", "Traveller nach Lee, Groß flach, Schrick in die Großschot, reffen", "Mehr Krängung zulassen", "Nichts"], "correct": 1, "expl": "Traveller nach Lee, Großsegel flach, Schrick in die Großschot und reffen reduzieren die Luvgierigkeit."}]};
FRAGEN["_Kurs/FB2/B2_Physikalische-Grundlagen/B2.2_Rumpfgeschwindigkeit.html"] = {n: "B.2.2", t: "Rumpfgeschwindigkeit", q: [{"q": "Wovon hängt die Rumpfgeschwindigkeit vor allem ab?", "opts": ["Von der Segelfläche", "Von der Wasserlinienlänge (LWL)", "Von der Motorleistung", "Von der Breite"], "correct": 1, "expl": "Die Rumpfgeschwindigkeit hängt von der Wasserlinienlänge ab: v ≈ 2,43 × √LWL."}, {"q": "Wie groß ist die Rumpfgeschwindigkeit bei LWL = 9 m etwa?", "opts": ["Ca. 5 kn", "Ca. 7,25 kn", "Ca. 10 kn", "Ca. 12 kn"], "correct": 1, "expl": "2,43 × √9 = 2,43 × 3 ≈ 7,25 kn."}, {"q": "Warum ist eine Übermotorisierung sinnlos?", "opts": ["Weil der Motor zu laut ist", "Weil der Verdränger nicht schneller als die Rumpfgeschwindigkeit wird", "Wegen des Verbrauchs allein", "Das stimmt nicht"], "correct": 1, "expl": "Ein Verdränger kann die Rumpfgeschwindigkeit nicht überschreiten – mehr Motorleistung bringt keine höhere Geschwindigkeit."}, {"q": "Welche Boote können die Rumpfgeschwindigkeit überschreiten?", "opts": ["Alle Kieljachten", "Gleitboote (Jollen)", "Nur Motorboote", "Keine"], "correct": 1, "expl": "Gleitboote (Jollen) reiten auf der eigenen Bugwelle und werden schneller."}]};
FRAGEN["_Kurs/FB2/B3_Bootsbau/B3.1_Material.html"] = {n: "B.3.1", t: "Baumaterial", q: [{"q": "Wofür steht GFK?", "opts": ["Guss-Faser-Kern", "Glasfaserverstärkter Kunststoff", "Gummi-Faser-Komposit", "Gel-Firnis-Kombination"], "correct": 1, "expl": "GFK ist glasfaserverstärkter Kunststoff (Epoxydharz + Glasfaser)."}, {"q": "Was ist Osmose beim GFK-Rumpf?", "opts": ["Eine Lackart", "Zersetzung des Laminats durch eindringendes Wasser", "Ein Beschlag", "Eine Kielform"], "correct": 1, "expl": "Osmose ist die durch eindringendes Wasser verursachte Zersetzung des Laminats bei mangelhafter Verarbeitung."}, {"q": "Welcher Nachteil kennzeichnet Stahlrümpfe?", "opts": ["Zu leicht", "Hohes Gewicht, Rost, Kondenswasser", "Zu teuer in der Wartung nie", "Osmose"], "correct": 1, "expl": "Stahl ist sehr fest, aber schwer, rostanfällig und neigt zu Kondenswasser."}, {"q": "Was muss bei Aluminium besonders verhindert werden?", "opts": ["Osmose", "Galvanische Korrosion (durch Isolieren)", "Rost", "Fäulnis"], "correct": 1, "expl": "Bei Aluminium ist die galvanische Korrosion durch sorgfältiges Isolieren zu unterbinden."}]};
FRAGEN["_Kurs/FB2/B3_Bootsbau/B3.2_Bauelemente.html"] = {n: "B.3.2", t: "Bauelemente", q: [{"q": "Was ist der Kiel im Bootsbau?", "opts": ["Das Deck", "Das Rückgrat vom Vorder- zum Achtersteven", "Ein Segel", "Ein Beschlag"], "correct": 1, "expl": "Der Kiel ist das Rückgrat des Rumpfes, an den die Spanten angefügt sind."}, {"q": "Wozu dient ein Kollisionsschott?", "opts": ["Zum Trimmen", "Es verhindert bei Havarie den Wassereinbruch ins ganze Schiff", "Als Ballast", "Als Ruder"], "correct": 1, "expl": "Das Kollisionsschott im Bug hält bei einer Havarie das Wasser vom übrigen Schiff fern."}, {"q": "Wie viel sollte der Ballast mindestens wiegen?", "opts": ["Ca. 5 %", "Mindestens etwa 25 % des Gesamtgewichts", "50 %", "Egal"], "correct": 1, "expl": "Der Ballast sollte mindestens rund 25 % des Gesamtgewichts betragen."}, {"q": "Was kennzeichnet einen Flossenkieler?", "opts": ["Großer Lateralplan, träge", "Kurzer, tiefer Kiel – schnell und wendig", "Kein Ballast", "Kein Ruder"], "correct": 1, "expl": "Der Flossenkieler hat einen kurzen, tiefen Kiel (oft mit Ballastbombe) – schnell und wendig."}, {"q": "Was ist ein Spatenruder?", "opts": ["Ein freistehendes Ruderblatt", "Ein Ruder als Kielfortsetzung", "Ein Ankertyp", "Ein Segel"], "correct": 0, "expl": "Ein Spatenruder ist ein freistehendes Ruderblatt (ohne vorgestellte Flosse)."}]};
